18	 * 管制事件数据访问。
19	 */
20	@Repository
21	public class ControlEventRepository {
22	
23	    private static final RowMapper<ControlEvent> MAPPER = (rs, n) -> new ControlEvent(
24	            rs.getLong("id"), rs.getLong("line_id"),
25	            ControlEventType.valueOf(rs.getString("type")),
26	            ControlEventStatus.valueOf(rs.getString("status")),
27	            rs.getObject("trigger_segment_id") == null ? null : rs.getLong("trigger_segment_id"),
28	            rs.getObject("avg_speed") == null ? null : rs.getDouble("avg_speed"),
29	            rs.getTimestamp("triggered_at").toInstant(),
30	            rs.getTimestamp("archived_at") == null ? null : rs.getTimestamp("archived_at").toInstant());
31	
32	    private static final String COLUMNS =
33	            "id, line_id, type, status, trigger_segment_id, avg_speed, triggered_at, archived_at";
34	
35	    private final JdbcTemplate jdbc;
36	
37	    public ControlEventRepository(JdbcTemplate jdbc) {
38	        this.jdbc = jdbc;
39	    }
40	
41	    /**
42	     * 新建管制事件，返回生成主键。
43	     */
44	    public long insert(long lineId, ControlEventType type, long triggerSegmentId, double avgSpeed,
45	                       Instant triggeredAt) {
46	        KeyHolder keys = new GeneratedKeyHolder();
47	        jdbc.update(con -> {
48	            var ps = con.prepareStatement(
49	                    "INSERT INTO control_event (line_id, type, status, trigger_segment_id, avg_speed, triggered_at) "
50	                            + "VALUES (?, ?, ?, ?, ?, ?)", new String[]{"id"});
51	            ps.setLong(1, lineId);
52	            ps.setString(2, type.name());
53	            ps.setString(3, ControlEventStatus.ACTIVE.name());
54	            ps.setLong(4, triggerSegmentId);
55	            ps.setDouble(5, avgSpeed);
56	            ps.setTimestamp(6, Timestamp.from(triggeredAt));
57	            return ps;
58	        }, keys);
59	        return keys.getKey().longValue();
60	    }
61	
62	    /**
63	     * 按 id 查询事件。
64	     */
65	    public Optional<ControlEvent> findById(long id) {
66	        return jdbc.query("SELECT " + COLUMNS + " FROM control_event WHERE id = ?", MAPPER, id)
67	                .stream().findFirst();
68	    }
69	
70	    /**
71	     * 按 id 查询并加行锁（事务内串行化事件级写操作）。
72	     */
73	    public Optional<ControlEvent> findByIdForUpdate(long id) {
74	        return jdbc.query("SELECT " + COLUMNS + " FROM control_event WHERE id = ? FOR UPDATE", MAPPER, id)
75	                .stream().findFirst();
76	    }
77	
78	    /**
79	     * 查询线路进行中（未归档）的事件。
