     */
    private void requireNoMaintenanceBlock(long lineId) {
        maintenanceRepository.findBlockingOrder(lineId, timeProvider.now())
                .ifPresent(order -> {
                    throw ApiException.conflict("检修封锁中禁止上客或复开: maintenanceOrderId=" + order.id());
                });
    }
}

